  "Host prod-web",
  "  HostName 10.0.0.11",
  "  User deploy",
  "  IdentityFile ~/.ssh/id_ed25519_prod",
  "  ServerAliveInterval 30",
  "",
  "Host staging",
  "  HostName 10.0.0.21",
  "  User root",
  "  PasswordAuthentication yes",
  "",
  "Host db-tunnel",
  "  HostName 10.0.0.31",
  "  User deploy",
  "  IdentityFile ~/.ssh/id_ed25519_prod",
  "  LocalForward 5433 db.internal:5432",
  "",
].join("\n");

function parseConfig(text) {
  const hosts = [];
  let cur = null;
  for (const raw of text.split("\n")) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    const [k, ...rest] = line.split(/\s+/);
    const v = rest.join(" ");
    if (k.toLowerCase() === "host") {
      cur = { host: v, opts: {} };
      hosts.push(cur);
    } else if (cur) {
      cur.opts[k.toLowerCase()] = v;
    }
  }
  return hosts;
}

const hosts = parseConfig(CONFIG);
console.log("hosts=" + hosts.map(h => h.host).join(","));

let rootLogin = 0;
let passwordAuth = 0;
let keyAuth = 0;
let forwards = 0;
for (const h of hosts) {
  const checks = [];
  const hasKey = Boolean(h.opts.identityfile);
  const isRoot = h.opts.user === "root";
  const usesPassword = (h.opts.passwordauthentication || "").toLowerCase() === "yes";
  const hasForward = Boolean(h.opts.localforward || h.opts.remoteforward || h.opts.dynamicforward);
  if (hasKey) keyAuth += 1;
  if (isRoot) rootLogin += 1;
  if (usesPassword) passwordAuth += 1;
  if (hasForward) forwards += 1;
  if (hasKey) checks.push("passwordless_key_auth");
  if (isRoot) checks.push("WARN_root_login");
  if (usesPassword) checks.push("WARN_password_auth_enabled");
  if (!hasKey && !usesPassword) checks.push("WARN_no_identity_file");
  if (hasForward) checks.push("port_forwarding");
  console.log("  " + h.host + " user=" + (h.opts.user || "-") + " checks=" + (checks.join(",") || "-"));
}

console.log("=== summary ===");
console.log("hosts_total=" + hosts.length);
